-- Generated by scripts/build-bob-text-hygiene-catalog.ts.
-- Owner decisions 2026-10-29: no internal references in Bob's chat answer, and
-- no stale stated sizes after construction changes. Apply
-- 20261029170000_construction_text_updates.sql and install both Bob runtimes
-- with the answer_text_version / construction_text_version consumers first.
-- Pinned manifests keep their earlier answers, texts and tool schemas.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $text_hygiene_publication$
declare spec jsonb:=$text_hygiene_spec${"additions":[{"key":"bob.note.answer-text","kind":"instruction_fragment","variables":["fragments"],"content":"Your reply contains internal references people should not read: {{fragments}}. Rewrite the same reply in plain words: name things by what they are, for example \"the box construction\" or \"the latest drawing\", and leave out IDs, codes, tool names and revision numbers. Do not read, save or change anything for this; return only the rewritten reply."},{"key":"bob.note.answer-text-also","kind":"instruction_fragment","variables":["fragments"],"content":"When you reply, also leave out the internal references in your previous reply ({{fragments}}): name things in plain words, without IDs, codes, tool names or revision numbers."}],"edits":[{"key":"agent-contract.ask-bob","requires":{"work_completion_version":3},"metadata":{"answer_text_version":1}},{"key":"tools.change_construction_parameters","requires":{"construction_work_version":1},"metadata":{"construction_text_version":1},"description_append":" text:null keeps the saved title and description. When either states a size this change alters, supply text with the complete corrected title and description (or leave sizes out of them); a change that would leave a stated overall size wrong is rejected without saving.","add_property":{"name":"text","schema":{"anyOf":[{"type":"object","additionalProperties":false,"required":["title","description"],"properties":{"title":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":5500}}},{"type":"null"}]}}},{"key":"tools.edit_construction_parts","requires":{"construction_work_version":1},"metadata":{"construction_text_version":1},"description_append":" text:null keeps the saved title and description. When either states a size this change alters, supply text with the complete corrected title and description (or leave sizes out of them); a change that would leave a stated overall size wrong is rejected without saving.","add_property":{"name":"text","schema":{"anyOf":[{"type":"object","additionalProperties":false,"required":["title","description"],"properties":{"title":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":5500}}},{"type":"null"}]}}}]}$text_hygiene_spec$::jsonb;
 item jsonb; prior shared.ai_prompt_versions; definition jsonb; next_version integer; prompt_uuid uuid; version_uuid uuid; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for item in select value from jsonb_array_elements(spec->'additions') loop
  if exists(select 1 from shared.ai_prompts where app='bob' and prompt_key=item->>'key') then
   if exists(select 1 from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
     where p.app='bob' and p.prompt_key=item->>'key' and v.metadata->>'text_hygiene_version'='1') then continue; end if;
   raise exception 'text_hygiene_key_taken: %',item->>'key';
  end if;
  insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
   values('bob',item->>'key',item->>'key','Text hygiene v1',item->>'content','',item->>'kind') returning id into prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,1,item->>'kind',1,jsonb_build_object('publication','bob-text-hygiene-v1','text_hygiene_version',1),
    item->>'content','{}'::jsonb,'',item->'variables') returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid);
 end loop;
 for item in select value from jsonb_array_elements(spec->'edits') loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
   where p.app='bob' and p.prompt_key=item->>'key' and p.retired_at is null for update of p;
  if not found then raise exception 'text_hygiene_contract_missing: %',item->>'key'; end if;
  if prior.metadata->>'text_hygiene_version'='1' then continue; end if;
  if not prior.metadata@>(item->'requires') then raise exception 'text_hygiene_requires: %',item->>'key'; end if;
  definition:=prior.definition;
  if item ? 'description_append' then
   definition:=jsonb_set(definition,'{description}',to_jsonb((definition->>'description')||(item->>'description_append')));
  end if;
  if item ? 'add_property' then
   if definition#>array['parameters','properties',item#>>'{add_property,name}'] is not null then raise exception 'text_hygiene_property_taken: %',item->>'key'; end if;
   definition:=jsonb_set(definition,array['parameters','properties',item#>>'{add_property,name}'],item#>'{add_property,schema}');
   definition:=jsonb_set(definition,'{parameters,required}',(definition#>'{parameters,required}')||to_jsonb(item#>>'{add_property,name}'));
   definition:=jsonb_set(definition,'{required_parameters}',(definition->'required_parameters')||to_jsonb(item#>>'{add_property,name}'));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,
    (prior.metadata-'seed_version'-'source_revision')||coalesce(item->'metadata','{}'::jsonb)
     ||jsonb_build_object('publication','bob-text-hygiene-v1','text_hygiene_version',1),
    prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid);
 end loop;
 if activation<>'{}'::jsonb then perform shared.activate_ai_catalog('bob',activation); end if;
end $text_hygiene_publication$;
commit;
